CREATE TABLE IF NOT EXISTS "route_header_templates" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT, "headers" JSONB NOT NULL, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
ALTER TABLE "token_routes" ADD COLUMN "custom_header_template_id" INTEGER;
ALTER TABLE "token_routes" ADD COLUMN "custom_headers" JSONB;
CREATE UNIQUE INDEX "route_header_templates_name_unique" ON "route_header_templates" ("name");
CREATE INDEX "token_routes_custom_header_template_id_idx" ON "token_routes" ("custom_header_template_id");
